package sdk

import (
	"encoding/json"
	"fmt"
	"strings"
)

const (
	diffContextLines = 3
	maxDiffCells     = 1_000_000
)

// DryRunSummaryPrefix is the optional stderr line prefix plugins can emit to
// provide a structured machine-readable summary for `semrel release --dry-run --output json`.
const DryRunSummaryPrefix = "plugin_dry_run_summary="

// UnifiedDiff computes a unified diff between before and after for the given
// file path entirely in memory. When before and after are identical, it returns
// an empty string. Large changed regions may be shown as full replacements.
func UnifiedDiff(path, before, after string) string {
	if before == after {
		return ""
	}
	cleanPath := strings.TrimPrefix(strings.ReplaceAll(path, "\\", "/"), "./")
	if cleanPath == "" {
		cleanPath = "file"
	}

	aLines := splitLines(before)
	bLines := splitLines(after)
	ops := diffLines(aLines, bLines)
	hunks := buildHunks(ops, diffContextLines)
	if len(hunks) == 0 {
		return ""
	}

	var b strings.Builder
	fmt.Fprintf(&b, "--- a/%s\n+++ b/%s\n", cleanPath, cleanPath)
	for _, h := range hunks {
		fmt.Fprintf(&b, "@@ -%d,%d +%d,%d @@\n", h.aStart, h.aCount, h.bStart, h.bCount)
		for _, line := range h.lines {
			b.WriteByte(line.kind)
			b.WriteString(line.text)
			if !strings.HasSuffix(line.text, "\n") {
				b.WriteString("\n\\ No newline at end of file\n")
			}
		}
	}
	return b.String()
}

// UnifiedDiffBytes computes a unified diff between two byte slices in memory.
func UnifiedDiffBytes(path string, before, after []byte) string {
	return UnifiedDiff(path, string(before), string(after))
}

// MaskSecret masks a secret string or webhook token for safe dry-run output.
func MaskSecret(value string) string {
	trimmed := strings.TrimSpace(value)
	if trimmed == "" {
		return ""
	}
	if len(trimmed) <= 8 {
		return "***"
	}
	return trimmed[:4] + "***"
}

// FormatDryRunSummary encodes a structured dry-run summary line suitable for
// writing to stderr.
func FormatDryRunSummary(summary map[string]interface{}) string {
	if len(summary) == 0 {
		return ""
	}
	data, err := json.Marshal(summary)
	if err != nil {
		return ""
	}
	return DryRunSummaryPrefix + string(data)
}

type editOp struct {
	kind byte // ' ', '-', '+'
	text string
	aIdx int
	bIdx int
}

type diffHunk struct {
	aStart int
	aCount int
	bStart int
	bCount int
	lines  []editOp
}

func splitLines(s string) []string {
	if s == "" {
		return nil
	}
	lines := strings.SplitAfter(s, "\n")
	if lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	return lines
}

func diffLines(a, b []string) []editOp {
	prefix := 0
	for prefix < len(a) && prefix < len(b) && a[prefix] == b[prefix] {
		prefix++
	}
	suffix := 0
	for suffix < len(a)-prefix && suffix < len(b)-prefix &&
		a[len(a)-1-suffix] == b[len(b)-1-suffix] {
		suffix++
	}

	ops := make([]editOp, 0, len(a)+len(b))
	i, j := 0, 0
	add := func(kind byte, text string) {
		ops = append(ops, editOp{kind: kind, text: text, aIdx: i + 1, bIdx: j + 1})
		if kind != '+' {
			i++
		}
		if kind != '-' {
			j++
		}
	}
	for i < prefix {
		add(' ', a[i])
	}

	old, new := a[prefix:len(a)-suffix], b[prefix:len(b)-suffix]
	n, m := len(old), len(new)
	if n > 0 && m > 0 && m <= maxDiffCells/n {
		dp := make([][]int, n+1)
		for row := range dp {
			dp[row] = make([]int, m+1)
		}
		for row := n - 1; row >= 0; row-- {
			for col := m - 1; col >= 0; col-- {
				if old[row] == new[col] {
					dp[row][col] = dp[row+1][col+1] + 1
				} else if dp[row+1][col] >= dp[row][col+1] {
					dp[row][col] = dp[row+1][col]
				} else {
					dp[row][col] = dp[row][col+1]
				}
			}
		}
		for i < prefix+n && j < prefix+m {
			row, col := i-prefix, j-prefix
			switch {
			case old[row] == new[col]:
				add(' ', old[row])
			case dp[row+1][col] >= dp[row][col+1]:
				add('-', old[row])
			default:
				add('+', new[col])
			}
		}
	}
	// Large changed regions are emitted as replacements to bound LCS memory.
	for i < prefix+n {
		add('-', a[i])
	}
	for j < prefix+m {
		add('+', b[j])
	}
	for i < len(a) {
		add(' ', a[i])
	}
	return ops
}

func buildHunks(ops []editOp, contextLines int) []diffHunk {
	type span struct{ start, end int }
	var changes []span
	for idx, op := range ops {
		if op.kind == ' ' {
			continue
		}
		s := idx - contextLines
		if s < 0 {
			s = 0
		}
		e := idx + contextLines + 1
		if e > len(ops) {
			e = len(ops)
		}
		if len(changes) > 0 && s <= changes[len(changes)-1].end {
			changes[len(changes)-1].end = e
		} else {
			changes = append(changes, span{start: s, end: e})
		}
	}

	hunks := make([]diffHunk, 0, len(changes))
	for _, ch := range changes {
		slice := ops[ch.start:ch.end]
		h := diffHunk{
			aStart: 1,
			bStart: 1,
			lines:  make([]editOp, 0, len(slice)),
		}
		if len(slice) > 0 {
			h.aStart = slice[0].aIdx
			h.bStart = slice[0].bIdx
		}
		for _, op := range slice {
			switch op.kind {
			case ' ':
				h.aCount++
				h.bCount++
			case '-':
				h.aCount++
			case '+':
				h.bCount++
			}
			h.lines = append(h.lines, op)
		}
		if h.aCount == 0 {
			h.aStart = 0
		}
		if h.bCount == 0 {
			h.bStart = 0
		}
		hunks = append(hunks, h)
	}
	return hunks
}
